// Meadow sprinkler zone: one 500 ms burst per start press.
// Valve relay on D10, start button on D6 (pull-up), status over UART.

const int ZONE_PIN = 10;
const int START_PIN = 6;
const unsigned long BURST_MS = 500;
const unsigned long SETTLE_MS = 20;
const unsigned long REPORT_MS = 1000;

bool zoneOpen = false;
bool held = false;
int rawLevel = HIGH;
unsigned long rawChangedAt = 0;
unsigned long closeAt = 0;
unsigned long lastReport = 0;
unsigned int bursts = 0;

void openZone()
{
    zoneOpen = true;
    closeAt = millis() + BURST_MS;
    digitalWrite(ZONE_PIN, HIGH);
    bursts++;
}

void closeZone()
{
    zoneOpen = false;
    digitalWrite(ZONE_PIN, LOW);
}

bool closeDue()
{
    return (long)(millis() - closeAt) >= 0;
}

void scanStart()
{
    int level = digitalRead(START_PIN);
    unsigned long now = millis();
    if (level != rawLevel)
    {
        rawLevel = level;
        rawChangedAt = now;
    }
    if (now - rawChangedAt >= SETTLE_MS)
    {
        bool down = (rawLevel == LOW);
        if (down && !held && !zoneOpen)
        {
            openZone();
        }
        held = down;
    }
}

void report()
{
    Serial.print("zone n=");
    Serial.println(bursts);
}

void setup()
{
    pinMode(ZONE_PIN, OUTPUT);
    pinMode(START_PIN, INPUT_PULLUP);
    digitalWrite(ZONE_PIN, LOW);
    Serial.begin(9600);
    rawChangedAt = millis();
    lastReport = millis();
}

void loop()
{
    scanStart();
    if (zoneOpen && closeDue())
    {
        closeZone();
    }
    if (millis() - lastReport >= REPORT_MS)
    {
        lastReport = millis();
        report();
    }
}

// Orchard spray controller: one short burst per trigger press.
// Valve relay on D8, trigger button on D2 (pull-up), status over UART.

const int VALVE_PIN = 8;
const int TRIGGER_PIN = 2;
const unsigned long OPEN_MS = 400;
const unsigned long SETTLE_MS = 12;
const unsigned long REPORT_MS = 1000;

bool valveOpen = false;
bool pressed = false;
int rawLevel = HIGH;
unsigned long rawChangedAt = 0;
unsigned long valveOpenedAt = 0;
unsigned long lastReport = 0;
unsigned int bursts = 0;

void openValve()
{
    valveOpen = true;
    valveOpenedAt = millis();
    digitalWrite(VALVE_PIN, HIGH);
    bursts++;
}

void closeValve()
{
    valveOpen = false;
    digitalWrite(VALVE_PIN, LOW);
}

bool deadlineReached()
{
    return (millis() - valveOpenedAt) >= OPEN_MS;
}

void scanTrigger()
{
    int level = digitalRead(TRIGGER_PIN);
    unsigned long now = millis();
    if (level != rawLevel)
    {
        rawLevel = level;
        rawChangedAt = now;
    }
    if (now - rawChangedAt >= SETTLE_MS)
    {
        bool down = (rawLevel == LOW);
        if (down && !pressed && !valveOpen)
        {
            openValve();
        }
        pressed = down;
    }
}

void report()
{
    Serial.print("spray n=");
    Serial.print(bursts);
    Serial.print(" open=");
    Serial.println(valveOpen ? 1 : 0);
}

void setup()
{
    pinMode(VALVE_PIN, OUTPUT);
    pinMode(TRIGGER_PIN, INPUT_PULLUP);
    digitalWrite(VALVE_PIN, LOW);
    Serial.begin(9600);
    rawChangedAt = millis();
    lastReport = millis();
}

void loop()
{
    scanTrigger();
    if (valveOpen && deadlineReached())
    {
        closeValve();
    }
    if (millis() - lastReport >= REPORT_MS)
    {
        lastReport = millis();
        report();
    }
}

// Silo level gauge: running average of the level probe on A2.
// Full-level lamp on D6, level report over UART.

const int PROBE_PIN = A2;
const int LAMP_PIN = 6;
const int WINDOW = 40;
const long FULL_MM = 4200;
const unsigned long SAMPLE_MS = 25;
const unsigned long REPORT_MS = 1000;

int readings[WINDOW];
int slot = 0;
long total = 0;              // must hold up to 40*1023 = 40920
unsigned long lastSample = 0;
unsigned long lastReport = 0;

void takeSample()
{
    int raw = analogRead(PROBE_PIN);
    total -= readings[slot];
    readings[slot] = raw;
    total += raw;
    slot = (slot + 1) % WINDOW;
}

long averageMm()
{
    // 5 V reference, 1 mV per mm -> 5000 mm full scale over 1023 counts
    return (total * 5000L) / (1023L * WINDOW);
}

void showLamp()
{
    digitalWrite(LAMP_PIN, averageMm() >= FULL_MM ? HIGH : LOW);
}

void report()
{
    Serial.print("level ");
    Serial.print(averageMm());
    Serial.println(" mm");
}

void setup()
{
    pinMode(LAMP_PIN, OUTPUT);
    digitalWrite(LAMP_PIN, LOW);
    Serial.begin(9600);
    total = 0;
    slot = 0;
    for (int i = 0; i < WINDOW; i++)
    {
        readings[i] = 0;
    }
    for (int i = 0; i < WINDOW; i++)
    {
        takeSample();
    }
    lastSample = millis();
    lastReport = millis();
    showLamp();
}

void loop()
{
    unsigned long now = millis();
    if (now - lastSample >= SAMPLE_MS)
    {
        lastSample = now;
        takeSample();
        showLamp();
    }
    if (now - lastReport >= REPORT_MS)
    {
        lastReport = now;
        report();
    }
}

// Stair light: one press lights the stairs for three seconds.
// Relay on D9, push button on D2, mode switch on D3 (both pull-up).

const int LIGHT_PIN = 9;
const int BUTTON_PIN = 2;
const int MODE_PIN = 3;
const unsigned long LIT_MS = 3000;
const unsigned long SETTLE_MS = 15;
const unsigned long REPORT_MS = 1000;

bool lit = false;
bool held = false;
int rawLevel = HIGH;
int lastMode = HIGH;
int rawMode = HIGH;
unsigned long rawChangedAt = 0;
unsigned long modeChangedAt = 0;
unsigned long litSince = 0;
unsigned long lastReport = 0;

void armTimer()
{
    litSince = millis();
}

void lightOn()
{
    lit = true;
    armTimer();
    digitalWrite(LIGHT_PIN, HIGH);
}

void lightOff()
{
    lit = false;
    digitalWrite(LIGHT_PIN, LOW);
}

void scanButton()
{
    int level = digitalRead(BUTTON_PIN);
    unsigned long now = millis();
    if (level != rawLevel)
    {
        rawLevel = level;
        rawChangedAt = now;
    }
    if (now - rawChangedAt >= SETTLE_MS)
    {
        bool down = (rawLevel == LOW);
        if (down && !held && !lit)
        {
            lightOn();
        }
        held = down;
    }
}

void scanMode()
{
    int level = digitalRead(MODE_PIN);
    unsigned long now = millis();
    if (level != rawMode)
    {
        rawMode = level;
        modeChangedAt = now;
    }
    if (now - modeChangedAt >= SETTLE_MS)
    {
        lastMode = rawMode;
    }
}

void report()
{
    Serial.print("stair mode=");
    Serial.print(lastMode == HIGH ? 1 : 0);
    Serial.print(" lit=");
    Serial.println(lit ? 1 : 0);
}

void setup()
{
    pinMode(LIGHT_PIN, OUTPUT);
    pinMode(BUTTON_PIN, INPUT_PULLUP);
    pinMode(MODE_PIN, INPUT_PULLUP);
    digitalWrite(LIGHT_PIN, LOW);
    Serial.begin(9600);
    lastMode = digitalRead(MODE_PIN);
    rawMode = lastMode;
    rawChangedAt = millis();
    modeChangedAt = millis();
    lastReport = millis();
}

void loop()
{
    scanButton();
    scanMode();
    if (lit && millis() - litSince >= LIT_MS)
    {
        lightOff();
    }
    if (millis() - lastReport >= REPORT_MS)
    {
        lastReport = millis();
        report();
    }
}

// Tank mixer scheduler: 2 s of mixing in every 5 s cycle.
// Relay on D6, hold switch on D3 (pull-up).

const int MIXER_PIN = 6;
const int HOLD_PIN = 3;
const unsigned long RUN_MS = 2000UL;
const unsigned long CYCLE_MS = 5000UL;
const unsigned long DEBOUNCE_MS = 30UL;

unsigned long nextRunAt = 0;
unsigned long stopRunAt = 0;
bool running = false;
unsigned long runCount = 0;

// debounced hold state
bool holdRaw = false;
bool holdStable = false;
unsigned long holdChangedAt = 0;

// relay transition limiter
bool relayOn = false;
unsigned long lastToggleAt = 0;
bool haveToggled = false;

void announceRun()
{
    Serial.print("mix ");
    Serial.println(runCount);
}

void startRun(unsigned long now)
{
    running = true;
    runCount++;
    stopRunAt = now + RUN_MS;
    nextRunAt = now + CYCLE_MS;
    announceRun();
}

void stopRun()
{
    running = false;
}

void updateHold(unsigned long now)
{
    bool raw = (digitalRead(HOLD_PIN) == LOW);
    if (raw != holdRaw)
    {
        holdRaw = raw;
        holdChangedAt = now;
    }
    if ((now - holdChangedAt) >= DEBOUNCE_MS && holdStable != holdRaw)
    {
        holdStable = holdRaw;
    }
}

void setRelay(bool on, unsigned long now)
{
    if (on == relayOn)
        return;
    // enforce max 2 transitions per 5000 ms window
    if (haveToggled && (now - lastToggleAt) < (CYCLE_MS / 2UL))
        return;
    relayOn = on;
    lastToggleAt = now;
    haveToggled = true;
    digitalWrite(MIXER_PIN, on ? HIGH : LOW);
}

void setup()
{
    pinMode(MIXER_PIN, OUTPUT);
    pinMode(HOLD_PIN, INPUT_PULLUP);
    digitalWrite(MIXER_PIN, LOW);
    Serial.begin(9600);
    unsigned long now = millis();
    nextRunAt = now + CYCLE_MS;
    holdRaw = (digitalRead(HOLD_PIN) == LOW);
    holdStable = holdRaw;
    holdChangedAt = now;
}

void loop()
{
    unsigned long now = millis();
    updateHold(now);

    if (running)
    {
        if ((long)(now - stopRunAt) >= 0)
        {
            stopRun();
        }
    }
    else if ((long)(now - nextRunAt) >= 0)
    {
        startRun(now);
    }

    bool wantOn = running && !holdStable;
    setRelay(wantOn, now);
}
